function flattenUnique(list, depth = 1, key = "id") {
  const output = [];
  const seen = new Set();

  function flat(items, currentDepth) {
    for (const item of items) {
      if (Array.isArray(item) && currentDepth > 0) {
        flat(item, currentDepth === Infinity ? Infinity : currentDepth - 1);
      } else {
        output.push(item);
      }
    }
  }

  flat(list, depth);
  const result = [];
  for (const item of output) {
    let mark;
    if (item && typeof item === "object" && Object.prototype.hasOwnProperty.call(item, key)) {
      mark = "obj:" + String(item[key]);
    } else if (item && typeof item === "object") {
      result.push(item);
      continue;
    } else {
      mark = typeof item + ":" + String(item);
    }
    if (!seen.has(mark)) {
      seen.add(mark);
      result.push(item);
    }
  }
  return result;
}

