test("支持外部 next", async () => {
  const calls = [];
  const fn = compose([async (ctx, next) => { calls.push("mw"); await next(); }]);
  await fn({}, async () => { calls.push("outer"); });
  assertEqual(calls, ["mw", "outer"]);
});

test("next 多次调用会 reject", async () => {
